// Small RGBA image class + procedural pixel-art painters.
// Every texture in CRAFTORIA is generated by this code at build time (no copied assets).
import fs from 'node:fs';
import path from 'node:path';
import { encodePNG, decodePNG } from './png.mjs';

export class Image {
  constructor(w, h, fill = [0, 0, 0, 0]) {
    this.w = w;
    this.h = h;
    this.data = new Uint8Array(w * h * 4);
    if (fill[3] !== 0 || fill[0] || fill[1] || fill[2]) this.fillRect(0, 0, w, h, fill);
  }
  static fromPNG(file) {
    const { width, height, data } = decodePNG(fs.readFileSync(file));
    const im = new Image(width, height);
    im.data.set(data);
    return im;
  }
  inside(x, y) { return x >= 0 && y >= 0 && x < this.w && y < this.h; }
  get(x, y) {
    if (!this.inside(x, y)) return [0, 0, 0, 0];
    const i = (y * this.w + x) * 4;
    return [this.data[i], this.data[i + 1], this.data[i + 2], this.data[i + 3]];
  }
  set(x, y, c) {
    x |= 0; y |= 0;
    if (!this.inside(x, y)) return;
    const i = (y * this.w + x) * 4;
    const a = c.length > 3 ? c[3] : 255;
    if (a >= 255 || this.data[i + 3] === 0) {
      this.data[i] = c[0]; this.data[i + 1] = c[1]; this.data[i + 2] = c[2]; this.data[i + 3] = a;
    } else {
      const t = a / 255;
      this.data[i] = Math.round(this.data[i] * (1 - t) + c[0] * t);
      this.data[i + 1] = Math.round(this.data[i + 1] * (1 - t) + c[1] * t);
      this.data[i + 2] = Math.round(this.data[i + 2] * (1 - t) + c[2] * t);
      this.data[i + 3] = Math.max(this.data[i + 3], a);
    }
  }
  fillRect(x, y, w, h, c) {
    for (let j = y; j < y + h; j++) for (let i = x; i < x + w; i++) this.set(i, j, c);
  }
  blit(src, dx, dy, sx = 0, sy = 0, w = src.w, h = src.h) {
    for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) {
      if (!src.inside(sx + i, sy + j) || !this.inside(dx + i, dy + j)) continue;
      const si = ((sy + j) * src.w + sx + i) * 4;
      const di = ((dy + j) * this.w + dx + i) * 4;
      this.data[di] = src.data[si]; this.data[di + 1] = src.data[si + 1];
      this.data[di + 2] = src.data[si + 2]; this.data[di + 3] = src.data[si + 3];
    }
  }
  scaled(f) {
    const out = new Image(this.w * f, this.h * f);
    for (let y = 0; y < out.h; y++) for (let x = 0; x < out.w; x++) {
      const si = (((y / f) | 0) * this.w + ((x / f) | 0)) * 4;
      const di = (y * out.w + x) * 4;
      for (let k = 0; k < 4; k++) out.data[di + k] = this.data[si + k];
    }
    return out;
  }
  save(file) {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, encodePNG(this.w, this.h, this.data));
  }
  hasTransparency() {
    for (let i = 3; i < this.data.length; i += 4) if (this.data[i] < 255) return true;
    return false;
  }
}

// ---------------------------------------------------------------------------
// Deterministic noise
export function hash2(x, y, seed = 0) {
  let h = (x * 374761393 + y * 668265263 + seed * 2147483647) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return ((h >>> 0) % 100000) / 100000;
}
export function strSeed(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}

export function hex(h, a = 255) {
  const v = parseInt(h.replace('#', ''), 16);
  return [(v >> 16) & 255, (v >> 8) & 255, v & 255, a];
}
export function mix(a, b, t) {
  return [0, 1, 2].map((k) => Math.round(a[k] * (1 - t) + b[k] * t)).concat([a[3] ?? 255]);
}
export function shade(c, f) {
  return [Math.max(0, Math.min(255, Math.round(c[0] * f))), Math.max(0, Math.min(255, Math.round(c[1] * f))), Math.max(0, Math.min(255, Math.round(c[2] * f))), c[3] ?? 255];
}

// ---------------------------------------------------------------------------
// Material palettes (original CRAFTORIA palette, industrial copper/brass/iron identity)
// tones: [darkest, dark, base, light, highlight]
export const MATERIALS = {
  andesite: { tones: ['#5b5e58', '#7d807a', '#9c9f98', '#b7bab2', '#cfd2ca'], pattern: 'stone' },
  andesite_dark: { tones: ['#3e413d', '#565953', '#6f726b', '#878a83', '#a0a39b'], pattern: 'stone' },
  brass: { tones: ['#6e4a1c', '#a5722c', '#d4a245', '#ecc767', '#fbe6a0'], pattern: 'metal' },
  brass_dark: { tones: ['#4a3112', '#6e4a1c', '#93652a', '#b58238', '#d4a245'], pattern: 'metal' },
  copper: { tones: ['#6b3220', '#9c4c2c', '#c86a3d', '#e48c5c', '#f6b48a'], pattern: 'metal' },
  copper_patina: { tones: ['#2f5a4e', '#3f7a66', '#55a086', '#78c1a3', '#a6dcc4'], pattern: 'metal' },
  iron: { tones: ['#5e6166', '#8b8f95', '#b4b8bd', '#d3d6da', '#eef0f2'], pattern: 'metal' },
  steel: { tones: ['#2b2e33', '#3d4148', '#535860', '#6b7179', '#8a9099'], pattern: 'metal' },
  gold: { tones: ['#8a5a0c', '#c48a14', '#eab42a', '#f8d555', '#fff1a8'], pattern: 'metal' },
  wood: { tones: ['#4b2e17', '#6a4223', '#8a5a32', '#a3703f', '#bb8650'], pattern: 'wood' },
  wood_light: { tones: ['#6e5130', '#93703f', '#b38d55', '#cba96c', '#dcc08a'], pattern: 'wood' },
  wood_dark: { tones: ['#2e1c0f', '#432a17', '#5a3a20', '#714a2a', '#8a5c35'], pattern: 'wood' },
  rubber: { tones: ['#1c1c1f', '#28282c', '#35353a', '#45454b', '#58585f'], pattern: 'stone' },
  stone: { tones: ['#4f4f52', '#6c6c70', '#8a8a8d', '#a5a5a8', '#bebec0'], pattern: 'stone' },
  granite: { tones: ['#5c4a44', '#7c665e', '#9a8279', '#b39c92', '#c9b5ab'], pattern: 'stone' },
  dark: { tones: ['#0f0f12', '#18181c', '#222227', '#2d2d33', '#393940'], pattern: 'flat' },
  canvas: { tones: ['#9c968a', '#bdb7a9', '#d9d3c4', '#ebe6d9', '#f7f4ec'], pattern: 'canvas' },
  glass: { tones: ['#5d8fa6', '#7fb2c6', '#a3d1e0', '#c6e7f0', '#ecf9fc'], pattern: 'glass' },
  redstone: { tones: ['#4a0b0b', '#7a1212', '#b01e1e', '#de3a2a', '#ff7a5c'], pattern: 'metal' },
  lapis: { tones: ['#142a66', '#1e3d8f', '#2c56b8', '#4876d6', '#7aa0ec'], pattern: 'metal' },
  white: { tones: ['#a9a9a9', '#c9c9c9', '#e2e2e2', '#f0f0f0', '#ffffff'], pattern: 'flat' },
  water: { tones: ['#1d3f8a', '#2a56b0', '#3a6fd0', '#5a8ee6', '#8ab4f4'], pattern: 'flat' },
  rope: { tones: ['#5a4126', '#7b5a36', '#9b7648', '#b8935e', '#d0ad78'], pattern: 'rope' },
  track_rail: { tones: ['#3a3d42', '#52565c', '#6c7178', '#8b9097', '#b0b5bb'], pattern: 'metal' },
  zinc: { tones: ['#55625f', '#7a8a86', '#a2b3ae', '#c3d2cd', '#e2ece9'], pattern: 'metal' },
};
for (const m of Object.values(MATERIALS)) m.c = m.tones.map((t) => hex(t));

/**
 * Paint a face rectangle.
 * face: { x, y, w, h, mat, seed, uLen, vLen, detail, border, grainAlongU }
 */
export function paintFace(img, f) {
  const mat = MATERIALS[f.mat];
  if (!mat) throw new Error('Unknown material ' + f.mat);
  const c = mat.c;
  const { x: X, y: Y, w, h } = f;
  const seed = f.seed ?? 1;
  const border = f.border ?? (w >= 3 && h >= 3);
  for (let j = 0; j < h; j++) {
    for (let i = 0; i < w; i++) {
      const n = hash2(i + X * 7, j + Y * 13, seed);
      let col;
      switch (mat.pattern) {
        case 'metal': {
          col = c[2];
          if (n > 0.86) col = c[3];
          else if (n < 0.12) col = mix(c[2], c[1], 0.6);
          // soft brushed streaks along u
          const streak = hash2(0, j + Y * 13, seed + 5);
          if (streak > 0.8 && n > 0.4) col = mix(col, c[3], 0.5);
          break;
        }
        case 'stone': {
          col = n > 0.8 ? c[3] : n > 0.55 ? c[2] : n > 0.25 ? mix(c[2], c[1], 0.5) : c[1];
          if (n > 0.96) col = c[4];
          break;
        }
        case 'wood': {
          // grain runs along the longer axis unless specified
          const alongU = f.grainAlongU ?? w >= h;
          const a = alongU ? j : i; // across-grain coordinate
          const b = alongU ? i : j; // along-grain coordinate
          const lane = hash2(a + (alongU ? Y : X) * 3, 0, seed + 11);
          col = lane > 0.66 ? c[3] : lane > 0.33 ? c[2] : mix(c[2], c[1], 0.55);
          const knot = hash2(a, Math.floor((b + (alongU ? X : Y)) / 3), seed + 17);
          if (knot > 0.93) col = c[1];
          // plank seams every 4 px across grain
          if (f.planks && (a + 1) % 4 === 0) col = c[1];
          break;
        }
        case 'canvas': {
          col = ((i + j) & 1) === 0 ? c[3] : c[2];
          if (n > 0.9) col = c[4];
          if (n < 0.06) col = c[1];
          break;
        }
        case 'glass': {
          col = c[2];
          if (i === j || i === j + 1) col = c[4];
          else if (n > 0.9) col = c[3];
          break;
        }
        case 'rope': {
          col = (i + j * 2) % 4 < 2 ? c[3] : c[1];
          if (n > 0.9) col = c[2];
          break;
        }
        default: {
          col = n > 0.85 ? c[3] : n < 0.15 ? c[1] : c[2];
        }
      }
      img.set(X + i, Y + j, col);
    }
  }
  if (border) {
    // bevel: light top/left, dark bottom/right
    for (let i = 0; i < w; i++) {
      img.set(X + i, Y, mix(img.get(X + i, Y), c[4], 0.45));
      img.set(X + i, Y + h - 1, c[0]);
    }
    for (let j = 0; j < h; j++) {
      img.set(X, Y + j, mix(img.get(X, Y + j), c[4], 0.3));
      img.set(X + w - 1, Y + j, mix(img.get(X + w - 1, Y + j), c[0], 0.75));
    }
  }
  if (f.detail) paintDetail(img, f, c);
}

function paintDetail(img, f, c) {
  const { x: X, y: Y, w, h } = f;
  const d = Array.isArray(f.detail) ? f.detail : [f.detail];
  for (const det of d) {
    switch (det) {
      case 'rivets': {
        if (w >= 6 && h >= 6) {
          for (const [i, j] of [[1, 1], [w - 2, 1], [1, h - 2], [w - 2, h - 2]]) {
            img.set(X + i, Y + j, c[4]);
          }
        }
        break;
      }
      case 'bolts': {
        if (w >= 4 && h >= 4) {
          const pts = [[1, 1], [w - 2, 1], [1, h - 2], [w - 2, h - 2]];
          for (const [i, j] of pts) { img.set(X + i, Y + j, c[0]); }
        }
        break;
      }
      case 'frame': {
        // 2px frame of base metal around inner panel (inner stays as painted by caller)
        break;
      }
      case 'grate': {
        for (let j = 1; j < h - 1; j++) for (let i = 1; i < w - 1; i++) {
          if (j % 2 === 0) img.set(X + i, Y + j, c[0]);
        }
        break;
      }
      case 'vstripes': {
        for (let j = 1; j < h - 1; j++) for (let i = 1; i < w - 1; i++) {
          if (i % 2 === 0) img.set(X + i, Y + j, c[1]);
        }
        break;
      }
      case 'center_dot': {
        const cx = X + Math.floor(w / 2), cy = Y + Math.floor(h / 2);
        img.set(cx, cy, c[0]);
        if (w % 2 === 0) img.set(cx - 1, cy, c[0]);
        if (h % 2 === 0) img.set(cx, cy - 1, c[0]);
        if (w % 2 === 0 && h % 2 === 0) img.set(cx - 1, cy - 1, c[0]);
        break;
      }
      case 'hazard': {
        for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) {
          if (((i + j) >> 1) % 2 === 0) img.set(X + i, Y + j, hex('#e8c020'));
          else img.set(X + i, Y + j, hex('#2a2a2a'));
        }
        break;
      }
      case 'arrow_u': {
        // arrow pointing towards +u
        const cy = Y + Math.floor(h / 2);
        for (let i = 1; i < w - 1; i++) img.set(X + i, cy, c[4]);
        for (let k = 1; k <= Math.min(2, Math.floor(h / 2) - 1); k++) {
          img.set(X + w - 2 - k, cy - k, c[4]);
          img.set(X + w - 2 - k, cy + k, c[4]);
        }
        break;
      }
      case 'dark_center': {
        if (w >= 4 && h >= 4) {
          for (let j = 1; j < h - 1; j++) for (let i = 1; i < w - 1; i++) img.set(X + i, Y + j, mix(img.get(X + i, Y + j), hex('#101014'), 0.75));
        }
        break;
      }
      default:
        break;
    }
  }
}
